def solve_final(grid):
    h, w = len(grid), len(grid[0])

    # Find highest region
    highest_start = -1
    for r in range(h):
        if any(c != 0 for c in grid[r]):
            highest_start = r
            break

    if highest_start == -1:
        return grid

    # Find highest region end
    region_end = highest_start
    for r in range(highest_start+1, h):
        if any(c != 0 for c in grid[r]):
            region_end = r
        else:
            break

    print(f"Highest region: rows {highest_start} to {region_end}")

    result = []
    for r in range(highest_start, region_end + 1):
        row = grid[r][:]

        # Fill from last non-zero onwards
        last_nz = max(c for c in range(w) if row[c] != 0)
        for c in range(last_nz + 1, w):
            row[c] = 1

        result.append(row)

    return result

